E("es-u2-211-q01",2,["EA12.2.11"],1,"var",varset([function(){return mcq("Which method of fossilization involves the replacement of the internal and external structures of hard parts by minerals, allowing for preservation of great detail?","replacement",["carbonization","distillation","pseudomorphism"],"In replacement, mineral matter substitutes for the original hard-part material cell by cell, preserving fine internal and external detail.",{});}]),["The original material is swapped for minerals."]);
E("es-u2-211-q02",2,["EA12.2.11"],1,"var",varset([function(){return mcq("Which would produce a trace fossil?","footprints and burrows",["body of an organism","foot bones","shell impressions"],"A trace fossil records an organism's activity rather than its body: footprints, burrows, trails and coprolites. Bones and shells are body fossils.",{});}]),["Trace fossils record behaviour, not body parts."]);
E("es-u2-211-q03",2,["EA12.2.11"],1,"var",varset([function(){var q=mcq("What type of fossil is illustrated in the diagram below?","trace",["body","carbon","cast"],"The diagram shows a footprint: evidence of an animal's activity, not a part of its body. Fossils of activity (footprints, burrows, trails) are trace fossils.",{});q.figure='<img src="banks/earth-3209/assets/u2-211-jun07-52.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Is it the animal itself, or something the animal did?"]);
E("es-u2-211-q04",2,["EA12.2.11"],1,"var",varset([function(){return mcq("Which process produces a fossil in which the pore spaces of an organic material are filled with minerals?","petrification",["carbonization","distillation","freezing"],"Petrification (permineralization) fills the pore spaces of wood or bone with mineral matter, turning the remains to stone while keeping their structure.",{});}]),["The spaces inside the material fill with minerals."]);
E("es-u2-211-q05",2,["EA12.2.11"],2,"var",varset([function(){return mcq("Which fossil is correctly matched with its method of formation? Fossil Method of Formation","foot prints: trace",["bones: mold and cast","coprolites: carbonization","frozen remains: petrification"],"Footprints are the classic trace fossil, the record of an animal's activity. Fossil excrement (coprolites) is also a trace fossil, not carbonization, and frozen remains are preserved whole, not petrified. (House fix: the source printed 'petrifaction'; the standard term is 'petrification'.)",{});}]),["One of these is a record of activity rather than a body part."]);
E("es-u2-211-q06",2,["EA12.2.11"],2,"var",varset([function(){return mcq("Which statement is correct about the fossil of a Miocene worm found in northern Canada?","No part of the worm is preserved.",["It consists of the remains of a hard body part.","The animal burrowed into a tar pit.","The burrow contains insect remains."],"A worm has no hard body parts, so nothing of the worm itself survives; what is preserved is its burrow, a trace fossil. The statement that no part of the worm is preserved is the correct one.",{});}]),["A worm is soft-bodied: what could actually be preserved?"]);

