E("es-u2-212-q01",2,["EA12.2.12"],2,"var",varset([function(){var q=mcq("Which factor most likely contributed to the position change of fossils in the diagram below?","the environment changed from a forest area to a freshwater lake",["the environment changed from a forest area to a marine environment","the environment changed from an ice-covered area to a marine environment","the environment became drier and more severe over time"],"Reading the column upward, plant fossils (fern, then leaves) give way to freshwater forms (shell, then fish): the area changed from forest to a freshwater lake environment over time.",{});q.figure='<img src="banks/earth-3209/assets/u2-212-jun06-54.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Read the fossils from the bottom (oldest) to the top (youngest)."]);
E("es-u2-212-q02",2,["EA12.2.12"],2,"var",varset([function(){return mcq("What evidence tells geologists that the supercontinent broke apart?","Fossils of Glossopteris are found on many continents.",["Boulders are found at the base of large mountains.","Cephalopods are found on both the Atlantic and Pacific coasts.","Fossil ivy leaves are found in Antarctica."],"Glossopteris was a land plant whose heavy seeds could not cross oceans, yet its fossils occur on South America, Africa, India, Australia and Antarctica. The continents must once have been joined, and have since broken apart and drifted.",{});}]),["The same land plant turns up on continents now separated by oceans."]);
E("es-u2-212-q03",2,["EA12.2.12"],2,"var",varset([function(){return mcq("Coal deposits, formed from lush tropical vegetation, are found in Antarctica. What does this evidence most directly suggest?","Antarctica's climate was once much warmer than it is today.",["Coal can form in any climate, including beneath polar ice caps.","The coal was carried to Antarctica by ocean currents.","Tropical plants are able to grow underneath Antarctic ice."],"Coal forms from dense vegetation in warm, swampy climates. Finding it in Antarctica means that land once supported a tropical climate, direct evidence that climate has changed over geologic time.",{});}]),["What climate does coal formation require?"]);

