E("es-u2-cr-q11",2,["EA12.2.4"],2,"var",varset([function(){var q=textq("The diagram below shows a granite (A) overlain by a shale (B). Describe two features that would indicate the contact between the two rock units is an erosion surface.",["Any two of: inclusions of granite A contained in shale B; no contact metamorphism at the base of the shale; the top of A is a weathered (exfoliation) surface; the surface of A is irregular."],"<b>Model answer:</b> Any two of the following indicate an erosion surface rather than an intrusive contact: (1) the shale B contains inclusions (fragments) of the granite A, showing the granite existed and was being eroded before the shale was deposited; (2) there is no contact metamorphism at the base of the shale, which an intruding hot granite would have produced; (3) the top of the granite is a weathered surface (exfoliation); (4) the surface of the granite is irregular, as an eroded land surface would be.<br><br><b>Marking points (2 marks):</b><br>- 1 mark for each of two valid features.<br><br>",{});q.figure='<img src="banks/earth-3209/assets/u2-24-jun06-63d.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Think about what an intrusion would do to the shale, and what erosion would leave behind."]);

