E("es-u2-cr-q14",2,["EA12.2.7"],2,"var",varset([function(){var q=textq("The diagram below shows the pattern of radioactive decay in a mineral sample. Use it to calculate the age of the sample. [ A = undecayed atoms, B = decayed atoms. In the diagram's key, an open circle is an undecayed atom and a solid circle is a decayed atom. The half-life for the radioactive sample is 2.3 million years. ]",["8 of 32 atoms remain undecayed, so 1/4 remains: 2 half-lives; age = 2 x 2.3 million = 4.6 million years."],"<b>Model answer:</b> Count the atoms in the grid: 8 of the 32 original atoms are still undecayed, so the fraction remaining is 8/32 = 1/4, which is 2 half-lives. Age = 2 x 2.3 million years = 4.6 million years.<br><br><b>Marking points (2 marks):</b><br>- 1 mark: the fraction remaining (1/4) converted to 2 half-lives.<br>- 1 mark: the age, 4.6 million years.<br><br>",{});q.figure='<img src="banks/earth-3209/assets/u2-27-aug07-61a.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Count undecayed atoms out of the total first."]);

