E("es-u2-cr-q15",2,["EA12.2.7"],2,"var",varset([function(){return textq("Radioactive element X has a half-life of 200,000 years. Given that there was originally 256 grams of element X in a rock, how much element X would be left if the rock is 1 million years old?",["1,000,000 / 200,000 = 5 half-lives; 256 to 128 to 64 to 32 to 16 to 8 g; 8 g remains."],"<b>Model answer:</b> Number of half-lives = 1,000,000 / 200,000 = 5. Halving 256 g five times: 128, 64, 32, 16, 8. So 8 g of element X remains.<br><br><b>Marking points (2 marks):</b><br>- 1 mark: determining that 5 half-lives have passed.<br>- 1 mark: the remaining mass, 8 g.<br><br>",{});}]),["Divide the rock's age by the half-life, then halve the mass that many times."]);

