E("es-u2-cr-q16",2,["EA12.2.7"],2,"var",varset([function(){return textq("Calculate the age of a mummified human if there is 6.25 percent of its original carbon-14 remaining. [Half-life of carbon-14 = 5,730 years]. Show all calculations.",["6.25% = 1/16 remaining, so 4 half-lives; age = 4 x 5,730 = 22,920 years."],"<b>Model answer:</b> Halving from 100 percent: 50, 25, 12.5, 6.25. Reaching 6.25 percent takes 4 half-lives. Age = 4 x 5,730 = 22,920 years.<br><br><b>Marking points (2 marks):</b><br>- 1 mark: determining that 4 half-lives have passed.<br>- 1 mark: the age, 22,920 years.<br><br>",{});}]),["Halve 100 percent until you reach 6.25 percent, and count the steps."]);

